// Fixture-driven tests for the PSD/PSB reader. The same logical document is
// generated by `test-assets/gen/gen-psd.mjs` in both v1 (PSD) and v2 (PSB) byte
// layouts, so one assertion set validates both code paths.

use monet_format::import::{
    parse, reconcile_psd_layer_blocks, Adjustment, BlendMode, Effect, LayerKind, SourceFormat,
};

const SAMPLE_PSD: &[u8] = include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/test-assets/fixtures/sample.psd"));
const SAMPLE_PSB: &[u8] = include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/test-assets/fixtures/sample.psb"));

fn layer<'a>(doc: &'a monet_format::import::Document, name: &str) -> &'a monet_format::import::Layer {
    doc.layers.iter().find(|l| l.name == name).unwrap_or_else(|| panic!("no layer named {name}; have {:?}", doc.layers.iter().map(|l| &l.name).collect::<Vec<_>>()))
}

fn check_sample(bytes: &[u8], expect_source: SourceFormat) {
    let doc = parse(bytes).expect("parse sample");
    assert_eq!(doc.source, expect_source);
    assert_eq!((doc.width, doc.height), (16, 16), "canvas size");
    assert_eq!(doc.depth, 8);

    // Background: full-canvas opaque dark grey.
    let bg = layer(&doc, "Background");
    assert_eq!(bg.kind, LayerKind::Raster);
    assert_eq!(bg.bounds.w, 16);
    assert_eq!(bg.bounds.h, 16);
    assert_eq!(&bg.rgba[0..4], &[40, 40, 40, 255], "bg pixel 0");
    assert!(bg.visible);
    assert_eq!(bg.blend, BlendMode::Normal);

    // Red Half: 50% opacity, multiply.
    let red = layer(&doc, "Red Half");
    assert!((red.opacity - 0.5).abs() < 0.01, "opacity {}", red.opacity);
    assert_eq!(red.blend, BlendMode::Multiply);
    assert_eq!(&red.rgba[0..4], &[200, 30, 30, 255]);

    // Gradient: every pixel unique (r=x*16, g=y*16, b=128) — proves RLE decode
    // and row/column placement byte-for-byte.
    let grad = layer(&doc, "Gradient");
    for y in 0..16usize {
        for x in 0..16usize {
            let i = (y * 16 + x) * 4;
            assert_eq!(grad.rgba[i], (x * 16) as u8, "grad r at {x},{y}");
            assert_eq!(grad.rgba[i + 1], (y * 16) as u8, "grad g at {x},{y}");
            assert_eq!(grad.rgba[i + 2], 128);
            assert_eq!(grad.rgba[i + 3], 255);
        }
    }

    // Hidden Blue: visibility flag.
    let hidden = layer(&doc, "Hidden Blue");
    assert!(!hidden.visible, "hidden layer should be invisible");

    // Group nesting: "Group" is a group; "Child" lives inside it and is offset.
    let group = layer(&doc, "Group");
    assert_eq!(group.kind, LayerKind::Group);
    assert!(group.pass_through, "ag-psd writes groups pass-through by default");
    let child = layer(&doc, "Child");
    assert_eq!(child.parent, Some(group.id), "Child must be parented to Group");
    assert_eq!((child.bounds.x, child.bounds.y), (4, 4), "child offset");
    assert_eq!((child.bounds.w, child.bounds.h), (8, 8), "child size");
    assert_eq!(&child.rgba[0..4], &[0, 128, 255, 255]);

    // Text + adjustment layers are present and classified.
    assert_eq!(layer(&doc, "Hi").kind, LayerKind::Text);
    assert_eq!(layer(&doc, "Bright").kind, LayerKind::Adjustment);

    // Bottom-to-top ordering: Background is the bottommost root layer.
    let first_root = doc.layers.iter().find(|l| l.parent.is_none()).unwrap();
    assert_eq!(first_root.name, "Background");
}

#[test]
fn reads_layered_psd() {
    check_sample(SAMPLE_PSD, SourceFormat::Psd);
}

#[test]
fn reads_layered_psb() {
    check_sample(SAMPLE_PSB, SourceFormat::Psb);
}

fn check_fidelity(bytes: &[u8]) {
    let doc = parse(bytes).expect("parse");

    // Stroke layer effect on the group child (lfx2 descriptor → Effect::Stroke).
    let child = layer(&doc, "Child");
    let stroke = child
        .effects
        .iter()
        .find_map(|e| match e {
            Effect::Stroke {
                color,
                opacity,
                size,
                position,
                ..
            } => Some((color, *opacity, *size, *position)),
            _ => None,
        })
        .expect("Child should carry a stroke effect");
    assert!(stroke.1.is_finite(), "stroke opacity must be a finite IR value");
    assert!((stroke.2 - 2.0).abs() < 0.5, "stroke size {}", stroke.2);
    assert_eq!(stroke.3, 0, "stroke position outside");
    assert!(stroke.0.r < 0.1 && stroke.0.g < 0.1 && stroke.0.b < 0.1, "black stroke");
    assert!(child
        .psd_smart_blocks
        .iter()
        .any(|block| &block.key == b"lfx2"));
    assert_eq!(
        reconcile_psd_layer_blocks(child, &child.psd_smart_blocks).unwrap(),
        child.psd_smart_blocks,
        "untouched lfx2 remains byte-exact"
    );

    // Text layer (TySh → editable Text + retained rendered pixels).
    let hi = layer(&doc, "Hi");
    let text = hi.text.as_ref().expect("text spec");
    assert_eq!(text.string, "Hi");
    assert_eq!(text.warp_style, 0, "no warp");
    assert!(text.point, "point text");
    assert!(hi
        .psd_smart_blocks
        .iter()
        .any(|block| &block.key == b"TySh"));
    assert_eq!(
        reconcile_psd_layer_blocks(hi, &hi.psd_smart_blocks).unwrap(),
        hi.psd_smart_blocks,
        "untouched TySh remains byte-exact"
    );

    // Brightness/contrast adjustment layer (brit → Adjustment::BrightnessContrast).
    let bright = layer(&doc, "Bright");
    match bright.adjustment.as_ref().expect("adjustment") {
        Adjustment::BrightnessContrast { brightness, contrast } => {
            assert!((*brightness - 0.40).abs() < 0.01, "brightness {brightness}");
            assert!((*contrast - 0.20).abs() < 0.01, "contrast {contrast}");
        }
        other => panic!("expected brightness/contrast, got {other:?}"),
    }
    assert!(bright
        .psd_smart_blocks
        .iter()
        .any(|block| &block.key == b"brit"));
    assert_eq!(
        reconcile_psd_layer_blocks(bright, &bright.psd_smart_blocks).unwrap(),
        bright.psd_smart_blocks,
        "untouched adjustment remains byte-exact"
    );
}

#[test]
fn reads_psd_fidelity() {
    check_fidelity(SAMPLE_PSD);
}

#[test]
fn reads_psb_fidelity() {
    check_fidelity(SAMPLE_PSB);
}

#[test]
fn psb_and_psd_agree_on_structure() {
    let a = parse(SAMPLE_PSD).unwrap();
    let b = parse(SAMPLE_PSB).unwrap();
    assert_eq!(a.layers.len(), b.layers.len());
    for (la, lb) in a.layers.iter().zip(b.layers.iter()) {
        assert_eq!(la.name, lb.name);
        assert_eq!(la.kind, lb.kind);
        assert_eq!(la.rgba, lb.rgba, "pixel mismatch on layer {}", la.name);
    }
}
